const $ = (s, root = document) => root.querySelector(s);
const main = $("#main"), modalRoot = $("#modal-root");
const state = { user: null, map: null, markerLayer: null, articles: [
  {slug:"field-notes",category:"FIELD NOTES",title:"A better field note starts before the visit",read:6,summary:"A practical template for recording what you observe without sharing sensitive details.",body:`<p>Good field notes help future readers understand what you actually saw, when you saw it, and what remains uncertain. They also keep a useful boundary between observation and rumor.</p><h2>Record what you can verify</h2><p>Start with the date, broad area, weather, and your vantage point. Describe visible condition and publicly available context in plain terms. Separate direct observations from reports you have not independently checked.</p><ul><li>Use a broad location label unless the owner has chosen to share exact coordinates.</li><li>Record the source and date for historical claims.</li><li>Do not include entry points, access-control weaknesses, alarm details, or private contact information.</li></ul><h2>Respect the place</h2><p>Stay on public routes, follow posted restrictions, and leave when access is not clearly permitted. A careful record is more useful than a risky visit.</p>`},
  {slug:"photo-stewardship",category:"PHOTOGRAPHY",title:"Photo stewardship for sensitive places",read:5,summary:"Share images with care: permissions, people, metadata, and context all matter.",body:`<p>Photographs can document change and make a place legible to a community. They can also expose people, private property, or fragile sites. Before sharing, think about who may be affected by each frame.</p><h2>Check the frame</h2><p>Remove identifying details when appropriate. Avoid showing security systems, access routes, personal documents, vehicle plates, or people who have not agreed to appear. Do not assume that a public road makes every subject safe to publish.</p><h2>Check the file</h2><p>Image files may contain device and location metadata. Urbexity stores media privately until moderation approves it; the public interface does not show pending uploads.</p>`},
  {slug:"responsible-exploration",category:"COMMUNITY",title:"A responsible exploration checklist",read:7,summary:"A short checklist for planning around permission, conditions, and other people.",body:`<p>Urban exploration is not permission to enter property. A location appearing on a map does not mean it is open, safe, or legal to visit.</p><h2>Before you go</h2><ul><li>Confirm access with the owner or an authorized public program.</li><li>Check current notices and local rules; do not rely on an old post.</li><li>Plan a legal alternative and tell someone your general itinerary.</li><li>Do not enter unstable, sealed, contaminated, or emergency-restricted structures.</li></ul><h2>While documenting</h2><p>Do not force entry, bypass security, remove objects, or disturb wildlife. Leave immediately if conditions change. Share context that helps others make responsible choices.</p>`},
  {slug:"community-guidelines",category:"POLICY",title:"Community guidelines",read:4,summary:"How Urbexity keeps discovery informative, respectful, and accountable.",body:`<p>Urbexity is for documentation, preservation-minded discussion, and lawful access. A listing never grants permission to enter a site.</p><h2>What belongs here</h2><p>Share original work, accurate context, and useful corrections. Respect landowners, neighbors, current occupants, and other explorers. Use approximate public coordinates unless you have a clear reason and permission to publish exact details.</p><h2>What we remove</h2><p>We may restrict content that encourages trespass, gives instructions for defeating security, exposes private personal data, promotes vandalism, infringes copyright, or creates a credible safety or privacy risk. Use the report action to request review.</p>`},
  {slug:"privacy",category:"POLICY",title:"Privacy and location data",read:5,summary:"How account visibility, approximate coordinates, and private media work.",body:`<p>Public profiles and public places are visible without signing in. Private profiles and private collections are checked by the server on every request.</p><p>Place coordinates are approximate by default in public responses. The owner can explicitly choose exact coordinates; private place coordinates are returned only to the owner and administrators. Uploaded images stay pending until approved. Session tokens are stored as hashes in D1 and issued in secure, HTTP-only cookies.</p><p>Use account settings to change profile visibility or request account deletion. Contact the site administrator for data export or privacy requests.</p>`},
  {slug:"api",category:"DEVELOPERS",title:"Urbexity API overview",read:3,summary:"Versioned, read-only public data API for approved KITE integrations.",body:`<p>Public lookups use the versioned API under <code>/api/v1</code>. Bot integrations should use a scoped bearer key issued by an administrator. Keys are hashed at rest, are shown only once, and can be revoked.</p><p>See <a href="/API.md">API.md</a> and <a href="/KITE-INTEGRATION.md">KITE-INTEGRATION.md</a> in the repository for complete examples. Requests are rate limited and private content is never returned by public endpoints.</p>`}
  ]};

async function api(path, options = {}) {
  const headers = new Headers(options.headers || {});
  if (options.body && !(options.body instanceof FormData)) headers.set("content-type", "application/json");
  const response = await fetch(`/api/v1${path}`, { credentials: "same-origin", ...options, headers, body: options.body && !(options.body instanceof FormData) ? JSON.stringify(options.body) : options.body });
  const type = response.headers.get("content-type") || "";
  if (!type.includes("json")) { if (response.ok) return {}; throw new Error("The request could not be completed."); }
  const data = await response.json(); if (!response.ok) throw new Error(data?.error?.message || "The request could not be completed."); return data;
}
function toast(message, type = "") { const el = document.createElement("div"); el.className = `toast ${type}`; el.textContent = message; $("#toast-region").append(el); setTimeout(() => el.remove(), 4200); }
function safe(s = "") { return String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])); }
function date(s) { return s ? new Intl.DateTimeFormat(undefined,{dateStyle:"medium"}).format(new Date(s)) : "Date unavailable"; }
function activeNav(path) { document.querySelectorAll(".main-nav a").forEach(a => a.classList.toggle("active",a.dataset.route===path || (path.startsWith("/places")&&a.dataset.route==="/") || (path.startsWith("/maps")&&a.dataset.route==="/maps"))); }
function goto(path) { history.pushState({},"",path); render(); window.scrollTo({top:0,behavior:"smooth"}); }
function card(place) {
  const image=place.coverUrl?`<img src="${safe(place.coverUrl)}" alt="${safe(place.title)}" loading="lazy">`:`<span class="card-placeholder">Awaiting community photos</span>`;
  const path=`/places/${place.slug||place.id}`;
  return `<a class="card" href="${path}" data-route="${path}"><div class="card-image">${image}</div><div class="card-content"><h2 class="card-title">${safe(place.title)}</h2><div class="card-meta"><span>⌖ ${safe([place.city,place.region,place.country].filter(Boolean).join(", ")||"Location withheld")}</span><span>${date(place.created_at)}</span></div>${place.description?`<p>${safe(place.description).slice(0,150)}</p>`:""}<div class="card-foot"><span>♡ ${Number(place.likes||0)}</span><span>◷ ${Number(place.views||0)}</span><span>◉ ${Number(place.comments||0)}</span></div></div></a>`;
}
function empty(title,description,action="") { return `<section class="empty-state"><h3>${safe(title)}</h3><p>${safe(description)}</p>${action}</section>`; }
async function refreshUser(){try{state.user=(await api("/auth/me")).user;}catch{state.user=null;}document.querySelectorAll("[data-auth-only]").forEach(e=>e.hidden=!state.user);document.querySelectorAll("[data-auth-guest]").forEach(e=>e.hidden=!!state.user);if(state.user&&$(".avatar-small"))$(".avatar-small").textContent=state.user.username.slice(0,1).toUpperCase();}

function home() {
  main.innerHTML=`<section class="hero"><div><span class="eyebrow">Urban exploration, with intention</span><h1>Discover the stories<br>left <em>behind.</em></h1><p>A community space to document places, preserve context, and find public, responsible ways to learn about the built environment.</p><div class="hero-actions"><a class="button button-primary" href="/discover" data-route="/discover">Explore places <span aria-hidden="true">↗</span></a><button class="button" data-action="new-place">Add a place</button></div></div><div class="hero-mark"><img src="/urbexity-logo.png" alt="Urbexity compass and location mark"><span class="hero-caption">Leave places as you found them</span></div></section>
  <div class="safety-note"><strong>Access matters.</strong> A listing is not permission to enter. Follow posted rules, confirm lawful access, and never force entry or compromise site security.</div>
  <h2 class="section-title">Explore the public map <span class="subtle">· approximate coordinates</span></h2><div class="map-layout"><div class="map-frame"><div id="explore-map" class="map-stage" role="application" aria-label="Interactive map of approved public locations"></div><div class="map-controls"><button data-action="map-zoom-in" aria-label="Zoom in">＋</button><button data-action="map-zoom-out" aria-label="Zoom out">−</button><button data-action="map-layers">Layers</button></div><div class="map-legend">⌖ Approved public listings · approximate by default</div></div><aside class="map-list"><strong>Recently documented</strong><div id="map-place-list" class="loading">Loading public places…</div></aside></div>
  <div class="page-head"><div><span class="eyebrow">Community contributions</span><h2 class="section-title">Recently added</h2></div><a class="button button-quiet" href="/discover" data-route="/discover">Browse all ↗</a></div><div id="recent-places" class="cards"></div>`;
  loadExplore();
}
async function loadExplore(){
  const mapNode=$("#explore-map");let leaflet=null;
  try { const data=await api("/places?limit=18");const places=data.data||[];const recent=$("#recent-places"),list=$("#map-place-list");if(recent)recent.innerHTML=places.slice(0,6).map(card).join("")||empty("The map is waiting for its first entry","Approved public locations will appear here once community submissions are reviewed.",`<button class="button button-primary" data-action="new-place">Submit a location</button>`);if(list)list.innerHTML=places.slice(0,8).map(p=>`<a class="place-list-item" href="/places/${p.slug}" data-route="/places/${p.slug}"><strong>${safe(p.title)}</strong><span>${safe([p.city,p.region].filter(Boolean).join(", ")||"Approximate area hidden")}</span></a>`).join("")||`<p class="subtle">No approved public locations yet. You can add a place if you have permission to share it.</p>`;
    if(mapNode&&window.L){const config=await api("/config").catch(()=>({tileUrl:"https://tile.openstreetmap.org/{z}/{x}/{y}.png"}));leaflet=L.map(mapNode,{zoomControl:false,scrollWheelZoom:false}).setView([39.5,-98.35],4);L.tileLayer(config.tileUrl||"https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:config.tileAttribution||"© OpenStreetMap contributors"}).addTo(leaflet);state.map=leaflet;state.markerLayer=window.L.markerClusterGroup?L.markerClusterGroup({showCoverageOnHover:false,spiderfyOnMaxZoom:true}):L.layerGroup();state.markerLayer.addTo(leaflet);places.forEach(p=>{const mk=L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:"",html:'<span class="map-pin"></span>',iconSize:[18,18],iconAnchor:[9,18]})});mk.bindPopup(`<b>${safe(p.title)}</b><br>${safe(p.category_label||"")}<br><a href="/places/${encodeURIComponent(p.slug)}">View details</a>`);mk.addTo(state.markerLayer);});}
  }catch(e){const recent=$("#recent-places"),list=$("#map-place-list");if(recent)recent.innerHTML=empty("The public directory is unavailable",e.message);if(list)list.textContent="Could not load public places.";}
}
async function discover(){main.innerHTML=`<div class="page-head"><div><span class="eyebrow">The public directory</span><h1>Discover places</h1><p>Explore community-documented places. Locations appear only after review; coordinates are approximate unless a contributor opted in to precision.</p></div><button class="button button-primary" data-action="new-place">＋ Add a place</button></div><form id="discover-form" class="searchbar"><input name="q" placeholder="Search places, regions, and cities" aria-label="Search locations"><button class="button button-primary">Search</button></form><div class="filters" id="category-filters"><button class="chip selected" data-category="all">All places</button></div><div class="page-head"><div id="result-caption" class="subtle">Loading locations…</div><label class="subtle">Sort <select id="sort-places" class="chip"><option value="newest">Newest</option><option value="oldest">Oldest</option><option value="views">Most viewed</option><option value="likes">Most liked</option></select></label></div><div id="discover-results" class="cards"></div><div id="discover-more" class="hero-actions"></div>`;
  const initial=new URLSearchParams(location.search);query=initial.get("q")||"";$("#discover-form input").value=query;let selected="all",page=1,sort="newest";const load=async(reset=true)=>{if(reset){page=1;$("#discover-results").innerHTML="<div class='loading'>Loading…</div>";}const params=new URLSearchParams({page,limit:24,sort});if(selected!=="all")params.set("category",selected);if(query)params.set("q",query);try{const d=await api(`/places?${params}`);const html=d.data.map(card).join("");if(reset)$("#discover-results").innerHTML=html||empty("No places match those filters","Try another category or search term. Public entries are reviewed before they appear.");else $("#discover-results").insertAdjacentHTML("beforeend",html);$("#result-caption").textContent=`${d.pagination.total} approved public ${d.pagination.total===1?"place":"places"}`;$("#discover-more").innerHTML=d.pagination.page<d.pagination.pages?`<button class="button" data-action="load-more">Load more</button>`:"";}catch(e){$("#discover-results").innerHTML=empty("Could not load locations",e.message);}};
  api("/categories").then(d=>{$("#category-filters").insertAdjacentHTML("beforeend",d.data.map(c=>`<button class="chip" data-category="${safe(c.slug)}">${safe(c.label)}</button>`).join(""));}).catch(()=>{});
  $("#discover-form").addEventListener("submit",e=>{e.preventDefault();query=new FormData(e.currentTarget).get("q").trim();load();});$("#category-filters").addEventListener("click",e=>{const c=e.target.closest("[data-category]");if(!c)return;selected=c.dataset.category;$("#category-filters").querySelectorAll(".chip").forEach(x=>x.classList.toggle("selected",x===c));load();});$("#sort-places").addEventListener("change",e=>{sort=e.target.value;load();});$("#discover-more").addEventListener("click",e=>{if(e.target.closest("[data-action=load-more]")){page++;load(false);}});load();
}
async function placeDetail(key){main.innerHTML="<div class='loading'>Loading location…</div>";try{const d=await api(`/places/${encodeURIComponent(key)}`),p=d.data;main.innerHTML=`<div class="page-head"><div><span class="eyebrow">${safe(p.category_label)} · ${safe(p.city||p.region||p.country||"Location")}</span><h1>${safe(p.title)}</h1><p>${safe([p.city,p.region,p.country].filter(Boolean).join(", ")||"Location details are limited by the contributor's privacy settings.")}</p></div><div class="hero-actions"><button class="button" data-action="share">Share</button><a class="button" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${p.latitude},${p.longitude}">Open map ↗</a></div></div><div class="two-col"><section><div class="panel"><h2>Photographs</h2><div class="cards">${p.photos.map(ph=>`<a class="card" href="${safe(ph.url)}" target="_blank"><div class="card-image"><img src="${safe(ph.url)}" alt="${safe(ph.alt_text||p.title)}"></div></a>`).join("")||empty("No approved photographs yet","Photos stay private until reviewed.")}</div>${state.user&&state.user.id===p.owner_id?`<form id="photo-upload" class="hero-actions"><label class="button">Upload photo<input type="file" name="file" accept="image/jpeg,image/png,image/webp,image/avif" hidden required></label><button class="button button-primary">Send for review</button></form>`:""}</div><div class="panel" style="margin-top:16px"><h2>About this place</h2><p class="subtle">${safe(p.description||"No description has been added.")}</p>${p.tags.length?`<div class="filters">${p.tags.map(t=>`<span class="chip">${safe(t)}</span>`).join("")}</div>`:""}${p.access_note?`<div class="safety-note">${safe(p.access_note)}</div>`:""}</div><div class="panel" style="margin-top:16px"><h2>Community notes</h2><div id="comments"></div>${state.user?`<form id="comment-form" class="form-grid"><label class="field">Add a note<textarea name="body" maxlength="2000" required></textarea></label><button class="button button-primary">Post note</button></form>`:`<p class="subtle">Sign in to leave a note.</p><button class="button" data-action="login">Sign in</button>`}</div></section><aside class="panel"><h2>Location details</h2><p><b>Documented by</b><br><a href="/u/${safe(p.owner.username)}" data-route="/u/${safe(p.owner.username)}">@${safe(p.owner.username)}</a></p><p><b>Added</b><br>${date(p.created_at)}</p><p><b>Views</b> · ${p.views}</p><p><b>Coordinates</b><br>${p.coordinate_precision==="exact"?"Contributor shared exact coordinates":"Approximate area only"}</p><div class="hero-actions"><button class="button" data-place-action="like" data-id="${safe(p.id)}">♡ Like · ${p.likes}</button><button class="button" data-place-action="bookmark" data-id="${safe(p.id)}">Save</button><button class="button" data-action="report" data-target="${safe(p.id)}">Report</button><button class="button" data-action="share">Copy link</button></div><div id="detail-map" class="map-frame" style="height:230px;min-height:230px;margin-top:18px"><div class="map-stage"></div></div><p class="subtle">Map position is approximate by default. Respect access restrictions.</p></aside></div>`;
    if(window.L&&$("#detail-map")){const m=L.map($("#detail-map")).setView([p.latitude,p.longitude],p.coordinate_precision==="exact"?13:9);L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap contributors"}).addTo(m);L.marker([p.latitude,p.longitude]).addTo(m);}
    loadComments(p.id);$("#comment-form")?.addEventListener("submit",async e=>{e.preventDefault();try{await api(`/places/${p.id}/comments`,{method:"POST",body:{body:new FormData(e.currentTarget).get("body")}});toast("Your note was added.","success");placeDetail(key);}catch(x){toast(x.message,"error");}});$("#photo-upload")?.addEventListener("submit",async e=>{e.preventDefault();try{const form=new FormData(e.currentTarget);await api(`/places/${p.id}/photos`,{method:"POST",body:form});toast("Photo submitted for moderation.","success");}catch(x){toast(x.message,"error");}});
  }catch(e){main.innerHTML=empty("Location unavailable",e.message,`<a class="button" href="/discover" data-route="/discover">Back to discover</a>`);}}
async function loadComments(id){try{const d=await api(`/places/${id}/comments`);$("#comments").innerHTML=d.data.length?d.data.map(c=>`<div class="place-list-item"><strong>@${safe(c.username)} · ${date(c.created_at)}</strong><p>${safe(c.body)}</p></div>`).join(""):`<p class="subtle">No community notes yet.</p>`;}catch{}}
async function profile(username){main.innerHTML="<div class='loading'>Loading profile…</div>";try{const d=await api(`/users/${encodeURIComponent(username)}`),p=d.data,places=(await api(`/users/${encodeURIComponent(username)}/places`)).data,maps=(await api(`/users/${encodeURIComponent(username)}/maps`)).data;main.innerHTML=`<div class="two-col"><section class="panel"><span class="eyebrow">Explorer profile</span><div style="display:flex;gap:20px;align-items:center;margin:14px 0 20px"><div class="avatar-small" style="width:70px;height:70px;font-size:28px">${safe(p.username.slice(0,1).toUpperCase())}</div><div><h1 style="font:600 34px 'Space Grotesk';margin:0">${safe(p.username)}</h1><p class="subtle">Member since ${date(p.joinedAt)}${p.location?` · ${safe(p.location)}`:""}</p></div></div><p>${safe(p.bio||"No bio provided.")}</p><div class="hero-actions">${state.user&&state.user.username!==p.username?`<button class="button button-primary" data-follow-user="${safe(p.username)}">Follow / unfollow</button><button class="button" data-action="message-user" data-user="${safe(p.username)}">Message</button><button class="button" data-action="report-user" data-target="${safe(p.id)}">Report</button>`:""}${state.user?.username===p.username?`<a class="button" href="/settings" data-route="/settings">Edit profile</a>`:""}</div><h2 class="section-title">Public contributions</h2><div class="stats-row">${Object.entries(p.stats).map(([k,v])=>`<div class="stat"><b>${Number(v).toLocaleString()}</b><span>${safe(k)}</span></div>`).join("")}</div></section><aside class="panel"><h2>Collections</h2>${maps.length?maps.map(m=>`<a class="place-list-item" href="/maps/${safe(m.slug)}" data-route="/maps/${safe(m.slug)}"><strong>${safe(m.title)}</strong><span>${m.place_count} places · ${date(m.created_at)}</span></a>`).join(""):"<p class='subtle'>No public collections yet.</p>"}</aside></div><h2 class="section-title">Public places</h2><div class="cards">${places.map(card).join("")||empty("No public locations yet","Approved public uploads will appear here.")}</div>`;}catch(e){main.innerHTML=empty("Profile unavailable",e.message);}}
async function mapsPage(){main.innerHTML=`<div class="page-head"><div><span class="eyebrow">Curated collections</span><h1>Maps & collections</h1><p>Build private field lists or publish a public collection from approved locations.</p></div><button class="button button-primary" data-action="new-map">＋ Create collection</button></div><div id="maps-grid" class="cards"><div class="loading">Loading collections…</div></div>`;try{const d=await api("/maps");$("#maps-grid").innerHTML=d.data.map(m=>`<a class="card" href="/maps/${safe(m.slug)}" data-route="/maps/${safe(m.slug)}"><div class="card-image"><span class="card-placeholder">${safe(m.place_count)} locations</span></div><div class="card-content"><h2 class="card-title">${safe(m.title)}</h2><div class="card-meta">@${safe(m.username)} · ${safe(m.visibility)}</div><p>${safe(m.description||"A community-curated collection.")}</p></div></a>`).join("")||empty("No public collections yet","Published collections will appear here.");}catch(e){$("#maps-grid").innerHTML=empty("Collections unavailable",e.message);}}
async function mapDetail(key){main.innerHTML="<div class='loading'>Loading collection…</div>";try{const d=await api(`/maps/${encodeURIComponent(key)}`),m=d.data,owner=state.user&&state.user.id===m.owner_id;main.innerHTML=`<div class="page-head"><div><span class="eyebrow">Collection by @${safe(m.username)}</span><h1>${safe(m.title)}</h1><p>${safe(m.description||"A curated field collection.")}</p></div><span class="chip">${safe(m.visibility)}</span></div><div class="safety-note">The map lists documented places, not permission to enter. Follow access rules and respect private property.</div>${owner?'<div class="hero-actions"><button class="button" data-map-add="'+safe(m.id)+'">Add a public place</button><button class="button" data-map-edit="'+safe(m.id)+'">Edit collection</button></div>':''}<div class="map-layout" style="margin-top:18px"><div class="map-frame"><div id="collection-map" class="map-stage"></div><div class="map-legend">Approved public entries only · approximate coordinates</div></div><aside class="map-list"><b>${m.places.length} locations</b>${m.places.map(p=>`<div class="place-list-item"><a href="/places/${safe(p.slug)}" data-route="/places/${safe(p.slug)}"><strong>${safe(p.title)}</strong><span>${safe(p.category_label||"")}</span></a>${owner?` <button class="chip" data-map-remove="${safe(m.id)}" data-place-id="${safe(p.id)}">Remove</button>`:''}</div>`).join("")||"<p class='subtle'>No visible places.</p>"}</aside></div>`;if(window.L){const map=L.map($("#collection-map")).setView([39.5,-98.35],4);L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap contributors"}).addTo(map);m.places.forEach(p=>L.marker([p.latitude,p.longitude]).addTo(map).bindPopup(safe(p.title)));}}catch(e){main.innerHTML=empty("Collection unavailable",e.message);}}
async function feed(){main.innerHTML=`<div class="page-head"><div><span class="eyebrow">From the field</span><h1>Community feed</h1><p>Approved field notes and photographs from explorers you follow and the wider community.</p></div><button class="button button-primary" data-action="new-post">＋ Share a note</button></div><div class="filters"><button class="chip selected">Recently added</button></div><div id="feed-items" class="cards"><div class="loading">Loading community posts…</div></div>`;try{const d=await api("/feed");$("#feed-items").innerHTML=d.data.map(x=>`<article class="card" data-post-id="${safe(x.id)}"><div class="card-image">${x.photoUrl?`<img src="${safe(x.photoUrl)}" alt="Community field photograph">`:`<span class="card-placeholder">Field note</span>`}</div><div class="card-content"><div class="card-meta">@${safe(x.username)} · ${date(x.created_at)}</div><h2 class="card-title">${safe(x.place_title||"Field note")}</h2><p>${safe(x.caption||"")}</p><div class="card-foot"><button class="chip" data-post-like="${safe(x.id)}">♡ ${x.likes}</button><button class="chip" data-post-comments="${safe(x.id)}">Comments</button>${x.place_id?`<a href="/places/${safe(x.place_id)}" data-route="/places/${safe(x.place_id)}">View place ↗</a>`:""}</div><div id="post-comments-${safe(x.id)}"></div></div></article>`).join("")||empty("The feed is quiet for now","Public posts appear after their photos are approved.",`<button class="button button-primary" data-action="new-post">Share a field note</button>`);}catch(e){$("#feed-items").innerHTML=empty("Feed unavailable",e.message);}}
function journal(){main.innerHTML=`<div class="page-head"><div><span class="eyebrow">Field journal</span><h1>Learn. Document. Respect.</h1><p>Practical notes on responsible documentation, privacy, photography, and caring for the places we study.</p></div></div><div class="article-grid">${state.articles.map(a=>`<article class="article"><span class="eyebrow">${a.category} · ${a.read} min read</span><h2>${safe(a.title)}</h2><p>${safe(a.summary)}</p><a class="button button-quiet" href="/journal/${a.slug}" data-route="/journal/${a.slug}">Read article ↗</a></article>`).join("")}</div>`;}
function article(slug){const a=state.articles.find(x=>x.slug===slug);if(!a){main.innerHTML=empty("Article not found","Choose a guide from the field journal.",`<a class="button" href="/journal" data-route="/journal">Field journal</a>`);return;}main.innerHTML=`<article class="article-detail"><a class="subtle" href="/journal" data-route="/journal">← Field journal</a><span class="eyebrow" style="display:block;margin-top:28px">${a.category} · ${a.read} min read</span><h1>${safe(a.title)}</h1><p class="subtle">${safe(a.summary)}</p><div>${a.body}</div><div class="safety-note">Urbexity promotes lawful access, privacy, and preservation. Never enter a property without permission.</div></article>`;}
async function leaderboard(){main.innerHTML=`<div class="page-head"><div><span class="eyebrow">Community contribution</span><h1>Contributors</h1><p>Rankings use actual approved public contributions. Choose a metric and time window.</p></div></div><div class="panel"><div class="filters"><label class="subtle">Period <select id="leader-period" class="chip"><option value="week">Week</option><option value="month" selected>Month</option><option value="year">Year</option><option value="all">All time</option></select></label><label class="subtle">Metric <select id="leader-category" class="chip"><option value="places">Places</option><option value="views">Views</option><option value="photos">Photos</option><option value="likes">Likes</option></select></label></div><div id="leader-results" class="leaderboard"></div></div>`;const load=async()=>{try{const d=await api(`/leaderboards?period=${$("#leader-period").value}&category=${$("#leader-category").value}`);$("#leader-results").innerHTML=d.data.map(x=>`<a class="leader-row" href="/u/${safe(x.username)}" data-route="/u/${safe(x.username)}"><span class="rank">#${x.rank}</span><span>@${safe(x.username)}<small>${safe(d.meta.method)}</small></span><b>${Number(x.score||0).toLocaleString()}</b></a>`).join("")||empty("No contributors in this period","Rankings appear after public contributions are approved.");}catch(e){$("#leader-results").innerHTML=empty("Rankings unavailable",e.message);}};$("#leader-period").addEventListener("change",load);$("#leader-category").addEventListener("change",load);load();}
async function market(){main.innerHTML=`<div class="page-head"><div><span class="eyebrow">Community exchange</span><h1>Market</h1><p>Curated digital field resources and map packs from community creators.</p></div>${state.user?`<button class="button button-primary" data-action="new-listing">＋ Draft a listing</button>`:""}</div><div class="price-disabled">Checkout is disabled until a payment provider is configured and verified. No payment details are collected here.</div><div id="market-items" class="cards" style="margin-top:18px"></div>`;try{const d=await api("/market");$("#market-items").innerHTML=d.data.map(x=>`<article class="card"><div class="card-image"><span class="card-placeholder">${safe(x.category)}</span></div><div class="card-content"><h2 class="card-title">${safe(x.title)}</h2><p>${safe(x.description)}</p><div class="card-meta">by @${safe(x.seller)} · ${(x.price_cents/100).toFixed(2)} ${safe(x.currency)}</div></div></article>`).join("")||empty("No published listings yet","Seller listings appear after an administrator publishes them.");}catch(e){$("#market-items").innerHTML=empty("Market unavailable",e.message);}}
async function settings(){if(!state.user){main.innerHTML=empty("Sign in required","Account settings are available after signing in.",`<button class="button button-primary" data-action="login">Sign in</button>`);return;}const d=await api("/profile");const p=d.data;main.innerHTML=`<div class="page-head"><div><span class="eyebrow">Your account</span><h1>Profile settings</h1><p>Your public profile is visible according to the settings below.</p></div></div><div class="two-col"><form id="profile-form" class="panel form-grid"><h2>Public profile</h2><label class="field">Username<input value="${safe(p.username)}" disabled><small>Username changes are not enabled yet.</small></label><label class="field">Bio<textarea name="bio" maxlength="500">${safe(p.bio)}</textarea></label><div class="field-row"><label class="field">Location label<input name="location" maxlength="120" value="${safe(p.location_label)}" placeholder="Optional region"></label><label class="field">Website<input name="website" type="url" value="${safe(p.website_url)}" placeholder="https://example.com"></label></div><label class="field">Profile visibility<select name="profileVisibility"><option value="public" ${p.profile_visibility==="public"?"selected":""}>Public</option><option value="private" ${p.profile_visibility==="private"?"selected":""}>Private</option></select></label><label class="field">Activity visibility<select name="activityVisibility"><option value="public" ${p.activity_visibility==="public"?"selected":""}>Public</option><option value="followers" ${p.activity_visibility==="followers"?"selected":""}>Followers</option><option value="private" ${p.activity_visibility==="private"?"selected":""}>Private</option></select></label><button class="button button-primary">Save profile</button></form><aside class="panel"><h2>Account</h2><p class="subtle">Email: ${safe(state.user.email)}</p><p class="subtle">Email verification: ${state.user.emailVerified?"verified":"not verified"}</p>${!state.user.emailVerified?`<button class="button" data-action="verify-email">Send verification email</button>`:""}<hr style="border-color:var(--line);margin:22px 0"><p class="subtle">Session cookies are secure and HTTP-only. Password reset links are emailed and expire after one hour.</p><button class="button" data-action="export-data">Download my data</button><hr style="border-color:var(--line);margin:22px 0"><h3>Deactivate account</h3><p class="subtle">Deactivate your account and remove its content from public access. This cannot be undone.</p><button class="button button-danger" data-action="delete-account">Delete my account</button></aside></div>`;$("#profile-form").addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api("/profile",{method:"PATCH",body:Object.fromEntries(f)});toast("Profile updated.","success");}catch(x){toast(x.message,"error");}});}
function messages(){if(!state.user){main.innerHTML=empty("Sign in to message","Conversations are private to their members.",`<button class="button button-primary" data-action="login">Sign in</button>`);return;}main.innerHTML=`<div class="page-head"><div><span class="eyebrow">Private conversations</span><h1>Messages</h1><p>Conversations are visible only to their participants.</p></div><button class="button button-primary" data-action="new-message">＋ New message</button></div><div id="conversations" class="leaderboard">Loading conversations…</div>`;api("/messages").then(d=>$("#conversations").innerHTML=d.data.map(x=>`<div class="leader-row"><span class="rank">✉</span><span>@${safe(x.username||"Explorer")}<small>${safe(x.last_message||"No messages")}</small></span><time class="subtle">${date(x.last_at)}</time></div>`).join("")||empty("No conversations yet","Start a conversation from an explorer profile.")).catch(e=>$("#conversations").innerHTML=empty("Messages unavailable",e.message));}
async function render(){const path=location.pathname.replace(/\/$/,"")||"/";activeNav(path);if(state.map){state.map.remove();state.map=null;}if(path==="/")return home();if(path==="/discover")return discover();if(path==="/feed")return feed();if(path==="/maps")return mapsPage();if(path.startsWith("/maps/"))return mapDetail(path.split("/")[2]);if(path.startsWith("/places/"))return placeDetail(path.split("/")[2]);if(path.startsWith("/u/"))return profile(decodeURIComponent(path.split("/")[2]));if(path==="/journal")return journal();if(path.startsWith("/journal/"))return article(path.split("/")[2]);if(path==="/leaderboard")return leaderboard();if(path==="/market")return market();if(path==="/settings")return settings();if(path==="/messages")return messages();if(path==="/login")return authModal("login");if(path==="/register")return authModal("register");main.innerHTML=empty("Page not found","That route is not part of Urbexity.",`<a class="button" href="/" data-route="/">Return to explore</a>`);}

function modal(title,content){modalRoot.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="modal-head"><h2>${safe(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div>${content}</section></div>`;$(".modal-backdrop",modalRoot).addEventListener("click",e=>{if(e.target.classList.contains("modal-backdrop"))closeModal();});$(".modal input",modalRoot)?.focus();}
function closeModal(){modalRoot.innerHTML="";}
function authModal(kind){const reg=kind==="register";modal(reg?"Create your account":"Welcome back",`<form id="auth-form" class="form-grid">${reg?`<label class="field">Username<input name="username" minlength="3" maxlength="30" autocomplete="username" required></label>`:""}<label class="field">Email<input name="email" type="email" autocomplete="email" required></label><label class="field">${reg?"Password":"Password"}<input name="password" type="password" minlength="12" maxlength="128" autocomplete="${reg?"new-password":"current-password"}" required><small>Use 12–128 characters.</small></label>${reg?`<div class="safety-note">By creating an account you agree to use Urbexity responsibly. A listing does not grant access permission.</div>`:""}<button class="button button-primary">${reg?"Create account":"Sign in"}</button>${!reg?`<button type="button" class="button button-quiet" data-action="forgot-password">Forgot password?</button>`:""}<p class="subtle">${reg?`Already a member? <button type="button" class="button button-quiet" data-action="switch-login">Sign in</button>`:`New here? <button type="button" class="button button-quiet" data-action="switch-register">Create an account</button>`}</p></form>`);$("#auth-form").addEventListener("submit",async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{const r=await api(`/auth/${reg?"register":"login"}`,{method:"POST",body:reg?b:{login:b.email,password:b.password}});state.user={id:r.user.id,username:r.user.username,email:b.email,emailVerified:r.user.emailVerified};closeModal();toast(reg?(r.verificationSent?"Account created. Check your email to verify it.":"Account created. Set RESEND_API_KEY to enable verification emails."):"Signed in.","success");await refreshUser();render();}catch(x){toast(x.message,"error");}});}
function promptForm(title,fields,submitLabel,handler){modal(title,`<form id="generic-form" class="form-grid">${fields}<button class="button button-primary">${submitLabel}</button></form>`);$("#generic-form").addEventListener("submit",async e=>{e.preventDefault();try{await handler(new FormData(e.currentTarget));closeModal();}catch(x){toast(x.message,"error");}});}
function placeForm(){if(!state.user){authModal("login");return;}promptForm("Document a place",`<label class="field">Name<input name="title" required minlength="3" maxlength="140"></label><label class="field">Category<select name="category"><option value="abandoned-building">Abandoned building</option><option value="factory">Factory</option><option value="hospital">Hospital</option><option value="school">School</option><option value="church">Church</option><option value="tunnel">Tunnel</option><option value="infrastructure">Infrastructure</option><option value="industrial">Industrial</option><option value="other">Other</option></select></label><label class="field">Description<textarea name="description" maxlength="4000" placeholder="Separate what you observed from what you have not verified."></textarea></label><div class="field-row"><label class="field">Latitude<input name="latitude" type="number" step="any" min="-90" max="90" required></label><label class="field">Longitude<input name="longitude" type="number" step="any" min="-180" max="180" required></label></div><div class="field-row"><label class="field">City<input name="city" maxlength="100"></label><label class="field">Region / state<input name="region" maxlength="100"></label></div><label class="field">Country<input name="country" maxlength="80"></label><label class="field">Visibility<select name="visibility"><option value="private">Private · only me</option><option value="unlisted">Unlisted · link access after approval</option><option value="public">Public · submitted for review</option></select></label><label class="field">Coordinate precision<select name="coordinatePrecision"><option value="approximate">Approximate (recommended)</option><option value="exact">Exact coordinates</option></select><small>Public map data is approximate by default. Private places are never publicly exposed.</small></label><div class="safety-note">Only submit places you are allowed to document. Do not share entry instructions, security weaknesses, or private personal information.</div>`,"Submit for review",async f=>{const body=Object.fromEntries(f);body.latitude=Number(body.latitude);body.longitude=Number(body.longitude);const d=await api("/places",{method:"POST",body});toast(d.message||"Location submitted.","success");});}
function newMap(){if(!state.user){authModal("login");return;}promptForm("Create a collection",`<label class="field">Name<input name="title" required minlength="3" maxlength="100"></label><label class="field">Description<textarea name="description" maxlength="2000"></textarea></label><label class="field">Visibility<select name="visibility"><option value="private">Private</option><option value="unlisted">Unlisted</option><option value="public">Public</option></select></label>`,"Create collection",async f=>{const d=await api("/maps",{method:"POST",body:Object.fromEntries(f)});toast("Collection created.","success");goto(`/maps/${d.data.slug}`);});}
function newPost(){if(!state.user){authModal("login");return;}modal("Share a field note",`<form id="post-form" class="form-grid"><label class="field">Caption<textarea name="caption" maxlength="2000" required></textarea></label><label class="field">Place ID (optional)<input name="placeId"></label><label class="field">Photo (optional)<input type="file" name="file" accept="image/jpeg,image/png,image/webp,image/avif"></label><button class="button button-primary">Share note</button></form>`);$("#post-form").addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(e.currentTarget),file=f.get("file");try{const post=await api("/feed",{method:"POST",body:{caption:f.get("caption"),placeId:f.get("placeId")||undefined}});if(file instanceof File&&file.size)await api(`/feed/${post.id}/photos`,{method:"POST",body:(()=>{const x=new FormData();x.set("file",file);return x;})()});closeModal();toast("Note created. Photo is pending moderation.","success");goto("/feed");}catch(x){toast(x.message,"error");}});}
function reportModal(target,type="place"){promptForm("Report content",`<label class="field">Reason<select name="reason"><option value="incorrect_information">Incorrect information</option><option value="privacy">Privacy concern</option><option value="copyright">Copyright complaint</option><option value="inappropriate">Inappropriate content</option><option value="safety">Safety concern</option><option value="other">Other</option></select></label><label class="field">Details<textarea name="details" maxlength="2000"></textarea></label>`,"Send report",async f=>{await api("/reports",{method:"POST",body:{...Object.fromEntries(f),targetType:type,targetId:target}});toast("Report sent to moderators.","success");});}

document.addEventListener("click",async e=>{
  const link=e.target.closest("a[data-route]");if(link){e.preventDefault();goto(link.dataset.route);$("body").classList.remove("mobile-nav-open");return;}
  const act=e.target.closest("[data-action]")?.dataset.action;
  if(act==="login"||act==="register")return authModal(act);
  if(act==="logout"){try{await api("/auth/logout",{method:"POST",body:{}});state.user=null;await refreshUser();toast("Signed out.","success");render();}catch(x){toast(x.message,"error");}}
  if(act==="close-modal")closeModal();if(act==="switch-login")authModal("login");if(act==="switch-register")authModal("register");
  if(act==="new-place")placeForm();if(act==="new-map")newMap();if(act==="new-post")newPost();if(act==="new-message"){promptForm("New message",`<label class="field">To (username)<input name="to" required></label><label class="field">Message<textarea name="body" maxlength="2000" required></textarea></label>`,"Send message",async f=>{await api("/messages",{method:"POST",body:Object.fromEntries(f)});toast("Message sent.","success");render();});}
  if(act==="new-listing"){if(!state.user)return authModal("login");promptForm("Draft a listing",`<label class="field">Title<input name="title" required maxlength="120"></label><label class="field">Description<textarea name="description" maxlength="4000"></textarea></label><label class="field">Category<input name="category" value="digital_map"></label><label class="field">Price in cents<input name="priceCents" type="number" min="0" max="100000000" required></label>`,"Save draft",async f=>{await api("/market",{method:"POST",body:{...Object.fromEntries(f),priceCents:Number(new FormData($("#generic-form")).get("priceCents"))}});toast("Draft saved. Checkout is disabled.","success");});}
  const mapAdd=e.target.closest("[data-map-add]");if(mapAdd){try{const mapId=mapAdd.dataset.mapAdd,places=(await api("/places?limit=48")).data;modal("Add a public place",`<form id="map-add-form" class="form-grid"><label class="field">Approved place<select name="placeId" required>${places.map(p=>`<option value="${safe(p.id)}">${safe(p.title)}</option>`).join("")}</select></label><button class="button button-primary">Add to collection</button></form>`);$("#map-add-form").addEventListener("submit",async ev=>{ev.preventDefault();try{await api(`/maps/${mapId}/places`,{method:"POST",body:{placeId:new FormData(ev.currentTarget).get("placeId")}});closeModal();toast("Place added to collection.","success");render();}catch(x){toast(x.message,"error");}});}catch(x){toast(x.message,"error");}}
  const mapRemove=e.target.closest("[data-map-remove]");if(mapRemove){try{await api(`/maps/${mapRemove.dataset.mapRemove}/places/${mapRemove.dataset.placeId}`,{method:"DELETE"});toast("Place removed from collection.","success");render();}catch(x){toast(x.message,"error");}}
  const mapEdit=e.target.closest("[data-map-edit]");if(mapEdit){const mapId=mapEdit.dataset.mapEdit;promptForm("Edit collection",`<label class="field">Name<input name="title" required maxlength="100"></label><label class="field">Description<textarea name="description" maxlength="2000"></textarea></label><label class="field">Visibility<select name="visibility"><option value="private">Private</option><option value="unlisted">Unlisted</option><option value="public">Public</option></select></label>`,"Save changes",async f=>{await api(`/maps/${mapId}`,{method:"PATCH",body:Object.fromEntries(f)});toast("Collection updated.","success");render();});}
  if(act==="delete-account"){if(!state.user)return;promptForm("Deactivate and remove your account",`<div class="safety-note">Your profile and uploaded content will be removed from public access. This action clears account data and cannot be undone.</div><label class="field">Type your username to confirm<input name="confirmUsername" required></label>`,"Delete account",async f=>{const confirmUsername=new FormData($("#generic-form")).get("confirmUsername");if(confirmUsername!==state.user.username)throw new Error("Username did not match.");await api("/profile",{method:"DELETE",body:{confirmUsername}});state.user=null;await refreshUser();toast("Account deactivated and content removed.","success");goto("/");});}
  const postLike=e.target.closest("[data-post-like]");if(postLike){if(!state.user)return authModal("login");try{const d=await api(`/feed/${postLike.dataset.postLike}/like`,{method:"POST",body:{}});postLike.textContent=d.liked?"♥ Liked":"♡ Like";}catch(x){toast(x.message,"error");}}
  const postComments=e.target.closest("[data-post-comments]");if(postComments){const postId=postComments.dataset.postComments,target=$(`#post-comments-${CSS.escape(postId)}`);if(!target)return;try{const d=await api(`/feed/${postId}/comments`);target.innerHTML=d.data.map(c=>`<p class="subtle">@${safe(c.username)}: ${safe(c.body)}</p>`).join("")||'<p class="subtle">No comments yet.</p>';if(state.user&&!$("#feed-comment-"+CSS.escape(postId))){target.insertAdjacentHTML("beforeend",`<form id="feed-comment-${safe(postId)}" class="form-grid"><label class="field">Add a comment<textarea name="body" maxlength="2000" required></textarea></label><button class="button">Post comment</button></form>`);$("#feed-comment-"+CSS.escape(postId)).addEventListener("submit",async ev=>{ev.preventDefault();try{await api(`/feed/${postId}/comments`,{method:"POST",body:{body:new FormData(ev.currentTarget).get("body")}});toast("Comment posted.","success");feed();}catch(x){toast(x.message,"error");}});}}catch(x){toast(x.message,"error");}}
  if(act==="verify-email"){try{const r=await api("/auth/verify",{method:"POST",body:{}});toast(r.sent?"Verification email sent.":"Email provider is not configured.",r.sent?"success":"error");}catch(x){toast(x.message,"error");}}
  if(act==="export-data"){try{const d=await api("/profile/export");const blob=new Blob([JSON.stringify(d.data,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="urbexity-account-export.json";a.click();URL.revokeObjectURL(a.href);toast("Your account export is ready.","success");}catch(x){toast(x.message,"error");}}
  if(act==="forgot-password")promptForm("Reset password",`<label class="field">Email<input type="email" name="email" required></label>`,"Send reset link",async f=>{const r=await api("/auth/reset/request",{method:"POST",body:Object.fromEntries(f)});toast(r.message,"success");});
  if(act==="search")promptForm("Search Urbexity",`<label class="field">Places, maps, or explorers<input name="q" minlength="2" required></label>`,`Search`,async f=>{const term=new FormData($("#generic-form")).get("q");closeModal();goto(`/discover?q=${encodeURIComponent(term)}`);});
  if(act==="share"){try{await navigator.clipboard.writeText(location.href);toast("Link copied.","success");}catch{toast(location.href);}}
  if(act==="report")reportModal(e.target.closest("[data-target]")?.dataset.target||"","place");if(act==="report-user")reportModal(e.target.closest("[data-target]")?.dataset.target||"","user");
  if(act==="message-user"){const username=e.target.closest("[data-user]").dataset.user;promptForm("Message explorer",`<label class="field">Message<textarea name="body" maxlength="2000" required></textarea></label>`,"Send",async f=>{await api("/messages",{method:"POST",body:{to:username,body:new FormData($("#generic-form")).get("body")}});toast("Message sent.","success");});}
  if(act==="menu")$("body").classList.toggle("mobile-nav-open");if(act==="map-zoom-in")state.map?.zoomIn();if(act==="map-zoom-out")state.map?.zoomOut();if(act==="map-layers")toast("Map data uses the configured public tile provider.");
  const follow=e.target.closest("[data-follow-user]");if(follow){if(!state.user)return authModal("login");try{const d=await api(`/users/${encodeURIComponent(follow.dataset.followUser)}/follow`,{method:"POST",body:{}});toast(d.active?"You are now following this explorer.":"Follow removed.","success");}catch(x){toast(x.message,"error");}}
  const action=e.target.closest("[data-place-action]");if(action){if(!state.user)return authModal("login");try{const d=await api(`/places/${action.dataset.id}/${action.dataset.placeAction}`,{method:"POST",body:{}});toast(action.dataset.placeAction==="like"?(d.liked?"Place liked.":"Like removed."):(d.bookmarked?"Place saved.":"Place removed from saved places."),"success");if(action.dataset.placeAction==="like")action.textContent=`${d.liked?"♥":"♡"} Like`;}catch(x){toast(x.message,"error");}}
});
document.addEventListener("submit",e=>{if(e.target.id==="generic-form")e.preventDefault();});
window.addEventListener("popstate",render);
await refreshUser();render();
